import re
from moler.exceptions import ParsingDone
from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg


__author__ = 'Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'dawid.gwizdz@nokia.com'


class Version(GenericRtg):
    """Version command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Version command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Version, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "version"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_build(line)
                self._parse_build_time(line)
            except ParsingDone:
                pass
        return super(Version, self).on_new_line(line, is_full_line)

    # Example line: Build        : RTG_RL11.0_BLD-51
    _re_build = re.compile(r"Build\s*:\s*(?P<BUILD>.*)$")

    def _parse_build(self, line):
        """
        Parse line contains build version in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_build, line):
            self.current_ret['BUILD'] = self._regex_helper.group('BUILD')
            raise ParsingDone

    # Example line: Build Time   : Tue Apr  2 13:39:15 2019
    _re_build_time = re.compile(r"Build Time\s*:\s*(?P<BUILD_TIME>.*)$")

    def _parse_build_time(self, line):
        """
        Parse line contains build time in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_build_time, line):
            self.current_ret['BUILD TIME'] = self._regex_helper.group('BUILD_TIME')
            raise ParsingDone


